D[9] = dict(title='دعای شوق به آمرزش', sub='درخواست توبه و دوری از پافشاری بر گناه',
 intro_ar='وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي الِاشْتِيَاقِ إِلَى طَلَبِ الْمَغْفِرَةِ مِنَ اللَّهِ جَلَّ جَلَالُهُ',
 intro_fa='از دعاهای امام سجاد (ع) در شوق به آمرزش‌خواهی از خدای بزرگ',
 p=[
('اللَّهُمَّ صَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَصَيِّرْنَا إِلَى مَحْبُوبِكَ مِنَ التَّوْبَةِ، وَأَزِلْنَا عَنْ مَكْرُوهِكَ مِنَ الْإِصْرَارِ.',
 'خدایا، بر محمد و خاندانش درود فرست، و ما را به توبه‌ای که دوست داری برسان، و از پافشاری بر گناه که ناخوشایند توست دور کن.'),
('اللَّهُمَّ وَمَتَى وَقَفْنَا بَيْنَ نَقْصَيْنِ فِي دِينٍ أَوْ دُنْيَا، فَأَوْقِعِ النَّقْصَ بِأَسْرَعِهِمَا فَنَاءً، وَاجْعَلِ التَّوْبَةَ فِي أَطْوَلِهِمَا بَقَاءً.',
 'خدایا، و هرگاه میان دو کاستی، در دین یا در دنیا، ماندیم، کاستی را در آن یک بینداز که زودتر از میان می‌رود، و توبه را در آن یک قرار ده که ماندگارتر است.'),
('وَإِذَا هَمَمْنَا بِهَمَّيْنِ يُرْضِيكَ أَحَدُهُمَا عَنَّا، وَيُسْخِطُكَ الْآخَرُ عَلَيْنَا، فَمِلْ بِنَا إِلَى مَا يُرْضِيكَ عَنَّا، وَأَوْهِنْ قُوَّتَنَا عَمَّا يُسْخِطُكَ عَلَيْنَا، وَلَا تُخَلِّ فِي ذٰلِكَ بَيْنَ نُفُوسِنَا وَاخْتِيَارِهَا، فَإِنَّهَا مُخْتَارَةٌ لِلْبَاطِلِ إِلَّا مَا وَفَّقْتَ، أَمَّارَةٌ بِالسُّوءِ إِلَّا مَا رَحِمْتَ.',
 'و هرگاه آهنگ دو کار کردیم که یکی تو را از ما خشنود می‌کند و دیگری تو را بر ما خشمگین، ما را به سوی آنچه تو را از ما خشنود می‌کند بکشان، و توان ما را برای آنچه تو را بر ما خشمگین می‌کند سست کن، و در این کار نفس‌های ما را به انتخاب خودشان وامگذار؛ زیرا نفس باطل را برمی‌گزیند مگر آنجا که تو توفیق دهی، و بسیار به بدی فرمان می‌دهد مگر آنجا که تو رحم کنی.'),
('اللَّهُمَّ وَإِنَّكَ مِنَ الضَّعْفِ خَلَقْتَنَا، وَعَلَى الْوَهْنِ بَنَيْتَنَا، وَمِنْ مَاءٍ مَهِينٍ ابْتَدَأْتَنَا، فَلَا حَوْلَ لَنَا إِلَّا بِقُوَّتِكَ، وَلَا قُوَّةَ لَنَا إِلَّا بِعَوْنِكَ.',
 'خدایا، تو ما را از ناتوانی آفریدی، و بر سستی بنا کردی، و از آبی بی‌مقدار آغاز کردی؛ پس ما را هیچ توانی نیست جز به نیروی تو، و هیچ نیرویی نیست جز به یاری تو.'),
('فَأَيِّدْنَا بِتَوْفِيقِكَ، وَسَدِّدْنَا بِتَسْدِيدِكَ، وَأَعْمِ أَبْصَارَ قُلُوبِنَا عَمَّا خَالَفَ مَحَبَّتَكَ، وَلَا تَجْعَلْ لِشَيْءٍ مِنْ جَوَارِحِنَا نُفُوذاً فِي مَعْصِيَتِكَ.',
 'پس ما را با توفیقت نیرو ده، و با راست‌گردانیِ خود به راه درست ببر، و چشمان دل‌های ما را بر آنچه با محبت تو ناسازگار است ببند، و برای هیچ‌یک از اندام‌های ما راهی به نافرمانی‌ات مگذار.'),
('اللَّهُمَّ فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَاجْعَلْ هَمَسَاتِ قُلُوبِنَا، وَحَرَكَاتِ أَعْضَائِنَا، وَلَمَحَاتِ أَعْيُنِنَا، وَلَهَجَاتِ أَلْسِنَتِنَا فِي مُوجِبَاتِ ثَوَابِكَ، حَتَّى لَا تَفُوتَنَا حَسَنَةٌ نَسْتَحِقُّ بِهَا جَزَاءَكَ، وَلَا تَبْقَى لَنَا سَيِّئَةٌ نَسْتَوْجِبُ بِهَا عِقَابَكَ.',
 'خدایا، پس بر محمد و خاندانش درود فرست، و زمزمه‌های دل‌ها، جنبش‌های اندام‌ها، نگاه‌های چشم‌ها و سخنان زبان‌های ما را در کارهایی قرار ده که پاداش تو را در پی دارد؛ تا هیچ نیکی‌ای که با آن سزاوار پاداشت شویم از دستمان نرود، و هیچ بدی‌ای که با آن سزاوار کیفرت شویم برایمان نماند.'),
])

D[10] = dict(title='دعای پناه بردن به خدا', sub='امید به عفو خدا و پناه به درگاه او',
 intro_ar='وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي اللَّجَإِ إِلَى اللَّهِ تَعَالَى',
 intro_fa='از دعاهای امام سجاد (ع) در پناه بردن به خدای بلندمرتبه',
 p=[
('اللَّهُمَّ إِنْ تَشَأْ تَعْفُ عَنَّا فَبِفَضْلِكَ، وَإِنْ تَشَأْ تُعَذِّبْنَا فَبِعَدْلِكَ.',
 'خدایا، اگر بخواهی از ما درگذری، از فضل توست؛ و اگر بخواهی عذابمان کنی، از عدل توست.'),
('فَسَهِّلْ لَنَا عَفْوَكَ بِمَنِّكَ، وَأَجِرْنَا مِنْ عَذَابِكَ بِتَجَاوُزِكَ، فَإِنَّهُ لَا طَاقَةَ لَنَا بِعَدْلِكَ، وَلَا نَجَاةَ لِأَحَدٍ مِنَّا دُونَ عَفْوِكَ.',
 'پس با احسانت عفوت را برای ما آسان کن، و با درگذشتنت ما را از عذابت پناه ده؛ زیرا ما تاب عدل تو را نداریم، و هیچ‌یک از ما جز با عفو تو رهایی ندارد.'),
('يَا غَنِيَّ الْأَغْنِيَاءِ، هَا، نَحْنُ عِبَادُكَ بَيْنَ يَدَيْكَ، وَأَنَا أَفْقَرُ الْفُقَرَاءِ إِلَيْكَ، فَاجْبُرْ فَاقَتَنَا بِوُسْعِكَ، وَلَا تَقْطَعْ رَجَاءَنَا بِمَنْعِكَ، فَتَكُونَ قَدْ أَشْقَيْتَ مَنِ اسْتَسْعَدَ بِكَ، وَحَرَمْتَ مَنِ اسْتَرْفَدَ فَضْلَكَ.',
 'ای بی‌نیازِ بی‌نیازان، اینک ما بندگان تو در برابرت هستیم، و من نیازمندترینِ نیازمندان به تو هستم؛ پس نیاز ما را با گشایش خود جبران کن، و امید ما را با دریغ کردنت قطع مکن؛ که در آن صورت کسی را که از تو نیک‌بختی خواسته بدبخت کرده‌ای، و کسی را که از فضل تو بخشش خواسته محروم ساخته‌ای.'),
('فَإِلَى مَنْ حِينَئِذٍ مُنْقَلَبُنَا عَنْكَ، وَإِلَى أَيْنَ مَذْهَبُنَا عَنْ بَابِكَ؟ سُبْحَانَكَ! نَحْنُ الْمُضْطَرُّونَ الَّذِينَ أَوْجَبْتَ إِجَابَتَهُمْ، وَأَهْلُ السُّوءِ الَّذِينَ وَعَدْتَ الْكَشْفَ عَنْهُمْ.',
 'آن‌گاه از نزد تو به سوی چه کسی بازگردیم، و از درگاه تو به کجا برویم؟ پاکی از آنِ توست! ما همان درماندگانیم که پاسخ دادن به آنان را بر خود واجب کرده‌ای، و همان گرفتارانِ بدی که وعدهٔ برطرف کردنش را داده‌ای.'),
('وَأَشْبَهُ الْأَشْيَاءِ بِمَشِيَّتِكَ، وَأَوْلَى الْأُمُورِ بِكَ فِي عَظَمَتِكَ، رَحْمَةُ مَنِ اسْتَرْحَمَكَ، وَغَوْثُ مَنِ اسْتَغَاثَ بِكَ، فَارْحَمْ تَضَرُّعَنَا إِلَيْكَ، وَأَغْنِنَا إِذْ طَرَحْنَا أَنْفُسَنَا بَيْنَ يَدَيْكَ.',
 'و سازگارترین چیز با خواست تو، و شایسته‌ترین کار به بزرگی‌ات، رحم کردن به کسی است که از تو رحمت خواسته، و به فریاد رسیدنِ کسی که از تو فریاد خواسته است؛ پس بر زاری ما به درگاهت رحم کن، و ما را بی‌نیاز کن، چون خود را در برابرت افکنده‌ایم.'),
('اللَّهُمَّ إِنَّ الشَّيْطَانَ قَدْ شَمِتَ بِنَا إِذْ شَايَعْنَاهُ عَلَى مَعْصِيَتِكَ، فَصَلِّ عَلَى مُحَمَّدٍ وَآلِهِ، وَلَا تُشْمِتْهُ بِنَا بَعْدَ تَرْكِنَا إِيَّاهُ لَكَ، وَرَغْبَتِنَا عَنْهُ إِلَيْكَ.',
 'خدایا، شیطان آن‌گاه که در نافرمانی تو از او پیروی کردیم، به حال ما شادی کرد؛ پس بر محمد و خاندانش درود فرست، و پس از آنکه او را به خاطر تو رها کردیم و از او روی گرداندیم و به تو رو آوردیم، او را به حال ما شاد مکن.'),
])

D[50] = dict(title='دعای ترس از خدا', sub='ترس از خدا و امید به رحمت او',
 intro_ar='وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي الرَّهْبَةِ',
 intro_fa='از دعاهای امام سجاد (ع) در ترس از خدا',
 p=[
('اللَّهُمَّ إِنَّكَ خَلَقْتَنِي سَوِيّاً، وَرَبَّيْتَنِي صَغِيراً، وَرَزَقْتَنِي مَكْفِيّاً.',
 'خدایا، تو مرا درست‌اندام آفریدی، و در کودکی پروراندی، و به اندازهٔ کفایت روزی دادی.'),
('اللَّهُمَّ إِنِّي وَجَدْتُ فِيمَا أَنْزَلْتَ مِنْ كِتَابِكَ، وَبَشَّرْتَ بِهِ عِبَادَكَ، أَنْ قُلْتَ: «يَا عِبَادِيَ الَّذِينَ أَسْرَفُوا عَلَى أَنْفُسِهِمْ لَا تَقْنَطُوا مِنْ رَحْمَةِ اللَّهِ، إِنَّ اللَّهَ يَغْفِرُ الذُّنُوبَ جَمِيعاً»، وَقَدْ تَقَدَّمَ مِنِّي مَا قَدْ عَلِمْتَ، وَمَا أَنْتَ أَعْلَمُ بِهِ مِنِّي، فَيَا سَوْأَتَا مِمَّا أَحْصَاهُ عَلَيَّ كِتَابُكَ!',
 'خدایا، من در کتابی که فرو فرستادی و بندگانت را با آن مژده دادی یافتم که فرمودی: «ای بندگان من که بر خود زیاده‌روی کرده‌اید، از رحمت خدا ناامید نشوید؛ همانا خدا همهٔ گناهان را می‌آمرزد.» و از من کارهایی سر زده که می‌دانی، و تو به آن از من داناتری؛ پس وای از رسوایی آنچه کتاب تو بر من شمرده است!'),
('فَلَوْلَا الْمَوَاقِفُ الَّتِي أُؤَمِّلُ مِنْ عَفْوِكَ الَّذِي شَمِلَ كُلَّ شَيْءٍ لَأَلْقَيْتُ بِيَدِي، وَلَوْ أَنَّ أَحَداً اسْتَطَاعَ الْهَرَبَ مِنْ رَبِّهِ لَكُنْتُ أَنَا أَحَقَّ بِالْهَرَبِ مِنْكَ، وَأَنْتَ لَا تَخْفَى عَلَيْكَ خَافِيَةٌ فِي الْأَرْضِ وَلَا فِي السَّمَاءِ إِلَّا أَتَيْتَ بِهَا، وَكَفَى بِكَ جَازِياً، وَكَفَى بِكَ حَسِيباً.',
 'اگر نبود جایگاه‌هایی که از عفو همه‌گیرت امید دارم، دست از خود می‌شستم [و خود را به نابودی می‌سپردم]. و اگر کسی می‌توانست از پروردگارش بگریزد، من سزاوارترین کس به گریختن از تو بودم؛ حال آنکه هیچ نهانی در زمین و آسمان بر تو پوشیده نیست مگر آنکه آن را [به حساب] می‌آوری؛ و تو برای پاداش دادن بسنده‌ای، و برای حسابرسی بسنده‌ای.'),
('اللَّهُمَّ إِنَّكَ طَالِبِي إِنْ أَنَا هَرَبْتُ، وَمُدْرِكِي إِنْ أَنَا فَرَرْتُ، فَهَا أَنَا ذَا بَيْنَ يَدَيْكَ خَاضِعٌ ذَلِيلٌ رَاغِمٌ، إِنْ تُعَذِّبْنِي فَإِنِّي لِذٰلِكَ أَهْلٌ، وَهُوَ يَا رَبِّ مِنْكَ عَدْلٌ، وَإِنْ تَعْفُ عَنِّي فَقَدِيماً شَمِلَنِي عَفْوُكَ، وَأَلْبَسْتَنِي عَافِيَتَكَ.',
 'خدایا، اگر بگریزم تو در پی من هستی، و اگر فرار کنم به من می‌رسی؛ پس اینک من در برابرت فروتن، خوار و سرافکنده‌ام. اگر عذابم کنی، سزاوار آنم، و آن، پروردگارا، از سوی تو عدل است؛ و اگر از من درگذری، از دیرباز عفوت مرا فرا گرفته و عافیتت را بر من پوشانده‌ای.'),
('فَأَسْأَلُكَ اللَّهُمَّ بِالْمَخْزُونِ مِنْ أَسْمَائِكَ، وَبِمَا وَارَتْهُ الْحُجُبُ مِنْ بَهَائِكَ، إِلَّا رَحِمْتَ هٰذِهِ النَّفْسَ الْجَزُوعَةَ، وَهٰذِهِ الرِّمَّةَ الْهَلُوعَةَ، الَّتِي لَا تَسْتَطِيعُ حَرَّ شَمْسِكَ، فَكَيْفَ تَسْتَطِيعُ حَرَّ نَارِكَ؟! وَالَّتِي لَا تَسْتَطِيعُ صَوْتَ رَعْدِكَ، فَكَيْفَ تَسْتَطِيعُ صَوْتَ غَضَبِكَ؟!',
 'پس خدایا، تو را به نام‌های نهفته‌ات، و به آن شکوهِ تو که پرده‌ها پوشانده است، می‌خوانم که بر این جانِ بی‌تاب و این استخوانِ پوسیدهٔ بی‌قرار رحم کنی؛ که تاب گرمای خورشیدت را ندارد، پس چگونه تاب گرمای آتشت را بیاورد؟! و تاب صدای رعدت را ندارد، پس چگونه تاب صدای خشمت را بیاورد؟!'),
('فَارْحَمْنِي اللَّهُمَّ فَإِنِّي امْرُؤٌ حَقِيرٌ، وَخَطَرِي يَسِيرٌ، وَلَيْسَ عَذَابِي مِمَّا يَزِيدُ فِي مُلْكِكَ مِثْقَالَ ذَرَّةٍ، وَلَوْ أَنَّ عَذَابِي مِمَّا يَزِيدُ فِي مُلْكِكَ لَسَأَلْتُكَ الصَّبْرَ عَلَيْهِ، وَأَحْبَبْتُ أَنْ يَكُونَ ذٰلِكَ لَكَ.',
 'پس خدایا، بر من رحم کن؛ که من مردی ناچیزم و قدرم اندک است، و عذاب من به اندازهٔ ذره‌ای بر فرمانروایی‌ات نمی‌افزاید؛ و اگر عذاب من چیزی بر فرمانروایی‌ات می‌افزود، از تو صبر بر آن را می‌خواستم و دوست داشتم که آن [افزایش] برای تو باشد.'),
('وَلٰكِنَّ سُلْطَانَكَ اللَّهُمَّ أَعْظَمُ، وَمُلْكَكَ أَدْوَمُ مِنْ أَنْ تَزِيدَ فِيهِ طَاعَةُ الْمُطِيعِينَ، أَوْ تَنْقُصَ مِنْهُ مَعْصِيَةُ الْمُذْنِبِينَ، فَارْحَمْنِي يَا أَرْحَمَ الرَّاحِمِينَ، وَتَجَاوَزْ عَنِّي يَا ذَا الْجَلَالِ وَالْإِكْرَامِ، وَتُبْ عَلَيَّ، إِنَّكَ أَنْتَ التَّوَّابُ الرَّحِيمُ.',
 'ولی خدایا، فرمانروایی‌ات بزرگ‌تر و پادشاهی‌ات پایدارتر از آن است که فرمان‌بریِ فرمان‌بران چیزی بر آن بیفزاید یا نافرمانیِ گناهکاران از آن بکاهد. پس بر من رحم کن، ای مهربان‌ترین مهربانان، و از من درگذر، ای صاحب شکوه و بزرگواری، و توبه‌ام را بپذیر؛ که تو بسیار توبه‌پذیر و مهربانی.'),
])

D[53] = dict(title='دعای فروتنی در برابر خدا', sub='اقرار به گناه و درخواست رحمت',
 intro_ar='وَكَانَ مِنْ دُعَائِهِ عَلَيْهِ السَّلَامُ فِي التَّذَلُّلِ لِلَّهِ عَزَّ وَجَلَّ',
 intro_fa='از دعاهای امام سجاد (ع) در فروتنی و خواری در برابر خدای عزیز و بزرگ',
 p=[
('رَبِّ أَفْحَمَتْنِي ذُنُوبِي، وَانْقَطَعَتْ مَقَالَتِي، فَلَا حُجَّةَ لِي، فَأَنَا الْأَسِيرُ بِبَلِيَّتِي، الْمُرْتَهَنُ بِعَمَلِي، الْمُتَرَدِّدُ فِي خَطِيئَتِي، الْمُتَحَيِّرُ عَنْ قَصْدِي، الْمُنْقَطَعُ بِي.',
 'پروردگارا، گناهانم زبانم را بسته و سخنم بریده شده است؛ پس هیچ دلیلی [برای دفاع] ندارم. منم که اسیر گرفتاری خویشم، در گروِ کردارم، سرگردان در خطایم، حیران و دور از مقصدم، و درمانده در راه.'),
('قَدْ أَوْقَفْتُ نَفْسِي مَوْقِفَ الْأَذِلَّاءِ الْمُذْنِبِينَ، مَوْقِفَ الْأَشْقِيَاءِ الْمُتَجَرِّئِينَ عَلَيْكَ، الْمُسْتَخِفِّينَ بِوَعْدِكَ.',
 'خود را در جایگاه خوارانِ گناهکار نگه داشته‌ام؛ در جایگاه تیره‌بختانی که بر تو گستاخی کردند و وعدهٔ تو را سبک شمردند.'),
('سُبْحَانَكَ! أَيَّ جُرْأَةٍ اجْتَرَأْتُ عَلَيْكَ، وَأَيَّ تَغْرِيرٍ غَرَّرْتُ بِنَفْسِي!',
 'پاکی از آنِ توست! چه گستاخی‌ای بر تو کردم، و خود را به چه خطری افکندم!'),
('مَوْلَايَ ارْحَمْ كَبْوَتِي لِحُرِّ وَجْهِي، وَزَلَّةَ قَدَمِي، وَعُدْ بِحِلْمِكَ عَلَى جَهْلِي، وَبِإِحْسَانِكَ عَلَى إِسَاءَتِي، فَأَنَا الْمُقِرُّ بِذَنْبِي، الْمُعْتَرِفُ بِخَطِيئَتِي، وَهٰذِهِ يَدِي وَنَاصِيَتِي، أَسْتَكِينُ بِالْقَوَدِ مِنْ نَفْسِي.',
 'مولای من، بر به رو افتادنم و لغزش گامم رحم کن، و با بردباری‌ات بر نادانی‌ام، و با نیکی‌ات بر بدی‌ام لطف کن؛ که من به گناهم اقرار دارم و به خطایم معترفم. این دست من و این پیشانی من است؛ فروتنانه خود را برای قصاص تسلیم می‌کنم.'),
('ارْحَمْ شَيْبَتِي، وَنَفَادَ أَيَّامِي، وَاقْتِرَابَ أَجَلِي، وَضَعْفِي، وَمَسْكَنَتِي، وَقِلَّةَ حِيلَتِي.',
 'بر پیری‌ام، و به سر رسیدن روزهایم، و نزدیک شدن مرگم، و ناتوانی و بیچارگی و کمیِ چاره‌ام رحم کن.'),
('مَوْلَايَ وَارْحَمْنِي إِذَا انْقَطَعَ مِنَ الدُّنْيَا أَثَرِي، وَامَّحَى مِنَ الْمَخْلُوقِينَ ذِكْرِي، وَكُنْتُ مِنَ الْمَنْسِيِّينَ كَمَنْ قَدْ نُسِيَ.',
 'مولای من، و بر من رحم کن آن‌گاه که نشانم از دنیا بریده شود، و یادم از میان آفریدگان پاک شود، و از فراموش‌شدگان گردم، مانند کسی که از یادها رفته است.'),
('مَوْلَايَ وَارْحَمْنِي عِنْدَ تَغَيُّرِ صُورَتِي وَحَالِي، إِذَا بَلِيَ جِسْمِي، وَتَفَرَّقَتْ أَعْضَائِي، وَتَقَطَّعَتْ أَوْصَالِي، يَا غَفْلَتِي عَمَّا يُرَادُ بِي!',
 'مولای من، و بر من رحم کن هنگامی که چهره و حالم دگرگون شود، آن‌گاه که تنم بپوسد، و اندام‌هایم از هم جدا شود، و بندهایم از هم بگسلد. وای از غفلت من از آنچه در پیش دارم!'),
('مَوْلَايَ وَارْحَمْنِي فِي حَشْرِي وَنَشْرِي، وَاجْعَلْ فِي ذٰلِكَ الْيَوْمِ مَعَ أَوْلِيَائِكَ مَوْقِفِي، وَفِي أَحِبَّائِكَ مَصْدَرِي، وَفِي جِوَارِكَ مَسْكَنِي، يَا رَبَّ الْعَالَمِينَ.',
 'مولای من، و در برانگیخته شدن و زنده شدنم بر من رحم کن، و در آن روز جایگاهم را با دوستانت، و بازگشتم را میان محبوبانت، و خانه‌ام را در جوار خودت قرار ده، ای پروردگار جهانیان.'),
])
